package bottlesong

import "fmt"

var numbers = map[int]string{
	0:  "no",
	1:  "One",
	2:  "Two",
	3:  "Three",
	4:  "Four",
	5:  "Five",
	6:  "Six",
	7:  "Seven",
	8:  "Eight",
	9:  "Nine",
	10: "Ten",
}

// countPhrase returns the count with the correct bottle pluralization,
// e.g. "Ten green bottles" or "One green bottle".
func countPhrase(n int) string {
	if n == 1 {
		return "One green bottle"
	}
	return numbers[n] + " green bottles"
}

func Recite(startBottles, takeDown int) []string {
	var verses []string
	for i := 0; i < takeDown; i++ {
		n := startBottles - i
		verses = append(verses,
			countPhrase(n)+" hanging on the wall,",
			countPhrase(n)+" hanging on the wall,",
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s hanging on the wall.", countPhrase(n-1)),
		)
		if i < takeDown-1 {
			verses = append(verses, "")
		}
	}
	return verses
}

