// countPhrase returns the count with the correct bottle pluralization,
// e.g. "Ten green bottles" or "One green bottle".
// When capitalize is false the count is lowercase, e.g. "nine green bottles".
func countPhrase(n int, capitalize bool) string {
	count := numbers[n]
	if capitalize {
		count = strings.Title(count)
	}
	bottles := "bottles"
	if n == 1 {
		bottles = "bottle"
	}
	return count + " green " + bottles
}

func Recite(startBottles, takeDown int) []string {
	var verses []string
	for i := 0; i < takeDown; i++ {
		n := startBottles - i
		verses = append(verses,
			countPhrase(n, true)+" hanging on the wall,",
			countPhrase(n, true)+" hanging on the wall,",
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s hanging on the wall.", countPhrase(n-1, false)),
		)
		if i < takeDown-1 {
			verses = append(verses, "")
		}
	}
	return verses
}

